/// <summary>
/// The helper class for Pack Change functionalitly
/// </summary>
class METItemPackChangeHelper
{
    InventItemPurchSetup inventItemPurchSetupTempItem;
    InventItemPurchSetup inventItemPurchSetupOrigItem;
    InventItemSalesSetup inventItemSalesSetupTempItem;
    InventItemSalesSetup inventItemSalesSetupOrigItem;
    WHSPhysDimUOM whsPhysDimUOMOrigItem;
    WHSPhysDimUOM whsPhysDimUOMTempItem;
    METInventItemOrderSetup metInventItemOrderSetupOrigItem;
    METInventItemOrderSetup metInventItemOrderSetupTempItem;
    InventSiteId            mainSiteId;
   
    InventParameters inventParameters = InventParameters::find();

    //Task 170637:CB409 - PE-128: D365 to PIM -start
    List siteList = new List(Types::String);
    List warehouseList = new List(Types::String);
}

