    /// <summary>
    /// Fill the data to run as user and call the service to change the status of the item
    /// </summary>
    public static void changeStatusRunAs(container _parm)
    {
        METInventItemOrderSetup     metInventItemOrderSetup;
        METInventItemOrderSetup     metInventItemOrderSetupTemp;
        InventItemPurchSetup        inventItemPurchSetupOrigItem;
        InventItemPurchSetup        inventItemPurchSetupTempItem;
        InventItemSalesSetup        inventItemSalesSetupOrigItem;
        InventItemSalesSetup        inventItemSalesSetupTempItem;
        WHSPhysDimUOM               whsPhysDimUOMOrig;
        WHSPhysDimUOM               whsPhysDimUOMTemp;

        METItemPackChangeHelper metItemPackChangeHelper = new METItemPackChangeHelper();
       
        RecId metInventItemOrderSetuprecId1, metInventItemOrderSetupTemprecId2, inventItemPurchSetupOrigItemrecId3, inventItemPurchSetupTempItemrecId4, 
            inventItemSalesSetupOrigItemrecId5, inventItemSalesSetupTempItemrecId6, whsPhysDimUOMOrigrecId7, whsPhysDimUOMTemprecId8;

        [metInventItemOrderSetuprecId1, metInventItemOrderSetupTemprecId2, inventItemPurchSetupOrigItemrecId3, inventItemPurchSetupTempItemrecId4, 
            inventItemSalesSetupOrigItemrecId5, inventItemSalesSetupTempItemrecId6, whsPhysDimUOMOrigrecId7, whsPhysDimUOMTemprecId8] = _parm;

        select firstOnly metInventItemOrderSetup
        where metInventItemOrderSetup.RecId == metInventItemOrderSetuprecId1;
        
        select firstOnly metInventItemOrderSetupTemp
        where metInventItemOrderSetupTemp.RecId == metInventItemOrderSetupTemprecId2;

        select firstOnly inventItemPurchSetupOrigItem
        where inventItemPurchSetupOrigItem.RecId == inventItemPurchSetupOrigItemrecId3;

        select firstOnly inventItemPurchSetupTempItem
        where inventItemPurchSetupTempItem.RecId == inventItemPurchSetupTempItemrecId4;

        select firstOnly inventItemSalesSetupOrigItem
        where inventItemSalesSetupOrigItem.RecId == inventItemSalesSetupOrigItemrecId5;

        select firstOnly inventItemSalesSetupTempItem
        where inventItemSalesSetupTempItem.RecId == inventItemSalesSetupTempItemrecId6;

        select firstOnly whsPhysDimUOMOrig
        where whsPhysDimUOMOrig.RecId == whsPhysDimUOMOrigrecId7;

        select firstOnly whsPhysDimUOMTemp
        where whsPhysDimUOMTemp.RecId == whsPhysDimUOMTemprecId8;

        metItemPackChangeHelper.parmMETInventItemOrderSetup(metInventItemOrderSetup);
        metItemPackChangeHelper.parmMETInventItemOrderSetupTempItem(metInventItemOrderSetupTemp);
        metItemPackChangeHelper.parmInventItemPurchSetupOrigItem(inventItemPurchSetupOrigItem);
        metItemPackChangeHelper.parmInventItemPurchSetupTempItem(inventItemPurchSetupTempItem);
        metItemPackChangeHelper.parmInventItemSalesSetupOrigItem(inventItemSalesSetupOrigItem);
        metItemPackChangeHelper.parmInventItemSalesSetupTempItem(inventItemSalesSetupTempItem);
        metItemPackChangeHelper.parmWHSPhysDimUOMOrigItem(whsPhysDimUOMOrig);
        metItemPackChangeHelper.parmWHSPhysDimUOMTempItem(whsPhysDimUOMTemp);

        if (metItemPackChangeHelper.validate())
        {
            metItemPackChangeHelper.startOperation();
        }
    }

    /// <summary>
    /// Runs the pack change operations
    /// </summary>
    public void startOperation()
    {
        #OCCRetryCount

        try
        {           
            mainSiteId = metInventItemOrderSetupOrigItem.SiteId;

            ttsbegin;

            this.createVendorListPrice();
            this.runPricingRoutine();
            this.createBarcode(metInventItemOrderSetupOrigItem, metInventItemOrderSetupTempItem);

            this.replaceOriginalItemSiteInfo(
                    inventItemPurchSetupOrigItem, inventItemPurchSetupTempItem, 
                    inventItemSalesSetupOrigItem, inventItemSalesSetupTempItem, 
                    metInventItemOrderSetupOrigItem, metInventItemOrderSetupTempItem);

            this.createPhysicalDim(metInventItemOrderSetupOrigItem, whsPhysDimUOMTempItem);
            this.unlinkTempItem();
            //this.updateItemStatus(metInventItemOrderSetupOrigItem, METConstants::Active);
            this.updateItemStatus(metInventItemOrderSetupTempItem, METConstants::Discontinued, true);
            this.rePriceOpenSalesOrders();
            //Task110346_CB409-D365ToPIM Main site id - start
            siteList.addEnd(metInventItemOrderSetupOrigItem.SiteId);
            this.populateWarehouseToBE(metInventItemOrderSetupOrigItem.SiteId, metInventItemOrderSetupOrigItem.ItemId);
            //Task110346_CB409-D365ToPIM Main site id - end            
            this.processNDCDependentSites();
            this.processCDSDependentSites();
            this.processCampbellsSubOrdinateSites();
            this.runVendorChangeRequest();        

            ttscommit;  
        
            //Task110346_CB409-D365ToPIM- start
            this.triggerItemPackchangeCompleteBusinessEvent(metInventItemOrderSetupOrigItem.ItemId, metInventItemOrderSetupTempItem.ItemId, siteList, warehouseList);
            //Task110346_CB409-D365ToPIM - end 
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch
        {
            throw error("@MET:UnhandledError");
        }
    }

    /// <summary>
    /// Runs the pack change operations for dependent site
    /// </summary>
    public void startOperation_DependentSites()
    {
        this.createPhysicalDim(metInventItemOrderSetupOrigItem, whsPhysDimUOMTempItem);
        this.createVendorListPrice();
        this.runPricingRoutine();
        this.createBarcode(metInventItemOrderSetupOrigItem, metInventItemOrderSetupTempItem);
        this.replaceOriginalItemSiteInfo(
                inventItemPurchSetupOrigItem, inventItemPurchSetupTempItem,
                inventItemSalesSetupOrigItem, inventItemSalesSetupTempItem,
                metInventItemOrderSetupOrigItem, metInventItemOrderSetupTempItem);
        this.unlinkTempItem();
        //this.updateItemStatus(metInventItemOrderSetupOrigItem, METConstants::Active);
        this.updateItemStatus(metInventItemOrderSetupTempItem, METConstants::Discontinued, true);
        this.rePriceOpenSalesOrders();

        this.runVendorChangeRequest();        

    }

    /// <summary>
    /// Validates the data supplied to this class
    /// </summary>
    /// <returns>Validation result</returns>
    public boolean validate()
    {
        boolean ret = true;
        boolean isControllingSite = false;

        if (!metInventItemOrderSetupOrigItem.RecId)
        {
            ret = checkFailed("@MET:METTempItemForPackChangeError");
        }

        if (!metInventItemOrderSetupOrigItem.TempItemPackChg)
        {
            ret = checkFailed(strFmt("@MET:TempItemNotLinked", metInventItemOrderSetupOrigItem.ItemId)) && ret;
        }

        ret = this.checkNDCSite() && ret;
        ret = this.checkCDSSite() && ret;
        ret = this.checkVendorChangeRequest() && ret;

        // Determine controlling site
        METSiteControllingAndSubOrdinateSetup metSiteControllingAndSubOrdinateSetup = this.getCampbellsControllingSite();

        if (metSiteControllingAndSubOrdinateSetup)
        {
            if (!metSiteControllingAndSubOrdinateSetup.IsControllingSite)
            {
                error(strFmt("@MET:CampbellsPackChangeError", metInventItemOrderSetupOrigItem.SiteId));
                ret = false;
                isControllingSite = false;
            }
            else
            {
                isControllingSite = true;
            }
        }

        //Validate for noncampbells sites or campbells controlling site
        if (!metSiteControllingAndSubOrdinateSetup || isControllingSite)
        {
            ret = this.checkSourceSiteIsPendingPackChange() && ret;
            ret = this.checkSourceSiteIsPendingPackChange_IntComp() && ret;
        }

        //Ignore validating for campbells controlling site
        if (!metSiteControllingAndSubOrdinateSetup)
        {
            // Only check stock if NOT a controlling site
            ret = this.checkStock() && ret;
        }

        ret = this.checkItemSubRange() && ret;

        return ret;
    }

    /// <summary>
    /// Check NDC site
    /// </summary>
    /// <returns>True or false</returns>
    private boolean checkNDCSite()
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;

        boolean ret = true;

        if (InventSite::find(metInventItemOrderSetupOrigItem.SiteId).METNDCSite)
        {
            select firstonly METNDCWarehouse_MainWarehouse from metReqItemTableInventDimView
                where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
                && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer;
            
            if (metReqItemTableInventDimView.METNDCWarehouse_MainWarehouse)
            {
                ret = checkFailed(strFmt("@MET:ValidationNDCSite", metInventItemOrderSetupOrigItem.SiteId));
            }      

        }
        return ret;
    }

    /// <summary>
    /// Check CDS site
    /// </summary>
    /// <returns>True or False</returns>
    private boolean checkCDSSite()
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        InventLocation inventLocation;

        boolean ret = true;
       
        select firstonly METCSDWarehouse from inventLocation
            exists join metReqItemTableInventDimView
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
            && metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer;
            
        if (inventLocation.METCSDWarehouse)
        {
            ret = checkFailed(strFmt("@MET:ValidationCDSSite", metInventItemOrderSetupOrigItem.SiteId));
        }
       
        return ret;
    }

    /// <summary>
    /// Check source site is pending
    /// </summary>
    /// <returns>True or false</returns>
    private boolean checkSourceSiteIsPendingPackChange()
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        METInventItemOrderSetup metInventItemOrderSetupTempItemLocal;

        boolean ret = true;

        select firstonly TempItemPackChg, SiteId from metInventItemOrderSetupTempItemLocal
            exists join metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
            && metReqItemTableInventDimView.MainWarehouseInventSiteId != metInventItemOrderSetupOrigItem.SiteId
            && metInventItemOrderSetupTempItemLocal.SiteId == metReqItemTableInventDimView.MainWarehouseInventSiteId
            && metInventItemOrderSetupTempItemLocal.ItemId == metInventItemOrderSetupOrigItem.ItemId;

        if (metInventItemOrderSetupTempItemLocal.TempItemPackChg)//Check for if temp Item is populated
        {
            ret = checkFailed(strFmt("@MET:ValidationSSS", metInventItemOrderSetupTempItemLocal.SiteId));
        }                       
       
        return ret;
    }

    /// <summary>
    /// Check source site Intercompany is pending
    /// </summary>
    /// <returns>True or false</returns>
    private boolean checkSourceSiteIsPendingPackChange_IntComp()
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        METInventItemOrderSetup metInventItemOrderSetupTempItemLocal;
        InventLocation inventLocation;

        boolean ret = true;
       
        select firstonly ItemId,CovInventDimId,ReqPOType,InventLocationIdReqMain, VendId, VendIntercompanyWarehouse from metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch
            && metReqItemTableInventDimView.METInterCompanySourced == NoYes::Yes;

        if (metReqItemTableInventDimView && metReqItemTableInventDimView.VendIntercompanyWarehouse)
        {
            changecompany(inventParameters.METInterCompanyPurchaseLegalEntity)
            {
                select firstonly InventSiteId from inventLocation
                    where inventLocation.InventLocationId == metReqItemTableInventDimView.VendIntercompanyWarehouse;

                if (inventLocation.InventSiteId)
                {
                    select firstonly RecId, TempItemPackChg
                        from metInventItemOrderSetupTempItemLocal
                        where metInventItemOrderSetupTempItemLocal.ItemId == metInventItemOrderSetupOrigItem.ItemId
                        && metInventItemOrderSetupTempItemLocal.SiteId == inventLocation.InventSiteId;

                    if (metInventItemOrderSetupTempItemLocal.TempItemPackChg)
                    {
                        // Bug 251804: CB885 - Error message incorrect for Intercompany Pack Change
                        ret = checkFailed(strFmt("@MET:ValidationSSS", inventLocation.InventSiteId));
                    }
                
                }
            }
        }
       
        return ret;
    }

    /// <summary>
    /// Checks the item stock
    /// </summary>
    /// <returns>true or false</returns>
    private boolean checkStock()
    {
        boolean ret = true;
        
        METReqItemTableInventDimView metReqItemTableInventDimView;       
        InventLocation inventLocation, inventLocationNDC;       

        select firstonly METNDCWarehouse, InventSiteId, InventLocationId from inventLocation
            exists join metReqItemTableInventDimView
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
            && metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId;

        if (inventLocation.METNDCWarehouse)
        {
            while select RecId, InventSiteId, InventLocationId
                    from inventLocationNDC
                    where inventLocationNDC.METNDCWarehouse == NoYes::Yes
            {
                ret = this.checkStockStatus(inventLocationNDC) && ret;
            }
        }
        else
        {
            ret = this.checkStockStatus(inventLocation) && ret;
        }
     

        return ret;
    }

    /// <summary>
    /// Check Stock Status
    /// </summary>
    /// <param name = "_inventLocation">InventLocation</param>
    /// <returns>true or false</returns>
    private boolean checkStockStatus(InventLocation _inventLocation)
    {
        boolean ret = true;

        InventWarehouseOnHandIncludingCWItemAggregatedView  inventOnHandView;

        select firstonly AvailableOnHandQuantityMapped, PdsCWAvailOnHandQuantityMapped, 
            OrderedQuantityMapped, PdsCWOrderedQuantityMapped, 
            ReservedOnHandQuantityMapped, PdsCWReservOnHandQuantityMapped
                from inventOnHandView
                where inventOnHandView.ItemNumber == metInventItemOrderSetupOrigItem.ItemId
                    && inventOnHandView.InventorySiteId == _inventLocation.InventSiteId
                    && inventOnHandView.InventoryWarehouseId == _inventLocation.InventLocationId;

        if (inventOnHandView.AvailableOnHandQuantityMapped || inventOnHandView.PdsCWAvailOnHandQuantityMapped)
        {
            ret = checkFailed(strfmt("@MET:OnHandValidation", metInventItemOrderSetupOrigItem.ItemId,_inventLocation.InventSiteId, _inventLocation.InventLocationId));
        }
        if (inventOnHandView.OrderedQuantityMapped || inventOnHandView.PdsCWOrderedQuantityMapped || inventOnHandView.ReservedOnHandQuantityMapped ||
                inventOnHandView.PdsCWReservOnHandQuantityMapped)
        {
            ret = checkFailed(strfmt("@MET:OpenPOTOValidation", metInventItemOrderSetupOrigItem.ItemId,_inventLocation.InventSiteId, _inventLocation.InventLocationId)) && ret;
        }       

        return ret;
    }

    /// <summary>
    /// Checks the item open purchase qty
    /// </summary>
    /// <returns>true or false</returns>
    private boolean checkOpenPurchQty()
    {
        boolean ret = true;

        InventTrans inventTrans;
        InventTransOrigin inventTransOrigin;

        select sum(Qty) from inventTrans
            where inventTrans.ItemId == metInventItemOrderSetupOrigItem.ItemId
                && inventTrans.StatusReceipt == StatusReceipt::Ordered
            exists join inventTransOrigin
                where inventTransOrigin.RecId == inventTrans.inventTransOrigin
                    && inventTransOrigin.ReferenceCategory == InventTransType::Purch;

        if (inventTrans.Qty > 0)
        {
            ret = checkFailed("@MET:METPackChangePurchQtyError");
        }

        return ret;
    }

    /// <summary>
    /// Yes No Dialog for Item Subrange
    /// </summary>
    /// <returns>true or false</returns>
    private boolean checkItemSubRange()
    {
        DialogButton res;
        boolean     ret = true;

        str message = strFmt("@MET:ItemIsAttachedToSubrange", metInventItemOrderSetupOrigItem.SubrangeId, metInventItemOrderSetupOrigItem.SubrangeDesc);
        
        if (metInventItemOrderSetupOrigItem.SubrangeId)
        {
            res = Box::yesNo(message, DialogButton::No, "@MET:PackChange");

            if (res == DialogButton::No)
            {
                ret = false;
            }
        }

        return ret;
    }

    /// <summary>
    /// Replace the original item info from temp item info
    /// </summary>
    /// <param name = "_inventItemPurchSetupOrigItem">InventItemPurchSetup table</param>
    /// <param name = "_inventItemPurchSetupTempItem">InventItemPurchSetup table</param>
    /// <param name = "_inventItemSalesSetupOrigItem">InventItemSalesSetup table</param>
    /// <param name = "_inventItemSalesSetupTempItem">InventItemSalesSetup table</param>
    /// <param name = "_metItemSiteSettingsSetupOriginal">METInventItemOrderSetup table</param>
    /// <param name = "_metInventItemOrderSetupTempItem">METInventItemOrderSetup table</param>
    private void replaceOriginalItemSiteInfo(InventItemPurchSetup _inventItemPurchSetupOrigItem,
                                            InventItemPurchSetup _inventItemPurchSetupTempItem,
                                            InventItemSalesSetup _inventItemSalesSetupOrigItem,
                                            InventItemSalesSetup _inventItemSalesSetupTempItem,
                                            METInventItemOrderSetup _metItemSiteSettingsSetupOriginal,
                                            METInventItemOrderSetup  _metInventItemOrderSetupTempItem)
    {             

        if (_inventItemPurchSetupOrigItem.RecId && _inventItemPurchSetupTempItem.RecId)
        {
            _inventItemPurchSetupOrigItem.selectForUpdate(true);
            _inventItemPurchSetupOrigItem.METPurchUnit = _inventItemPurchSetupTempItem.METPurchUnit;
            _inventItemPurchSetupOrigItem.update();
        }

        if (_inventItemSalesSetupOrigItem.RecId && _inventItemSalesSetupTempItem.RecId)
        {
            _inventItemSalesSetupOrigItem.selectForUpdate(true);
            _inventItemSalesSetupOrigItem.METSalesUnit = _inventItemSalesSetupTempItem.METSalesUnit;
            _inventItemSalesSetupOrigItem.update();
        }

        _metItemSiteSettingsSetupOriginal.selectForUpdate(true);
        _metItemSiteSettingsSetupOriginal.CartonPerLayer = _metInventItemOrderSetupTempItem.CartonPerLayer;        
        _metItemSiteSettingsSetupOriginal.Layers = _metInventItemOrderSetupTempItem.Layers;
        _metItemSiteSettingsSetupOriginal.RetailUnitLUCPack = _metInventItemOrderSetupTempItem.RetailUnitLUCPack;
        _metItemSiteSettingsSetupOriginal.modifiedField(fieldNum(METInventItemOrderSetup,CartonPerLayer));
        _metItemSiteSettingsSetupOriginal.update();
        
    }

    /// <summary>
    /// Creates Physical dimensions
    /// </summary>
    /// <param name = "_metInventItemOrderSetupOrigItem">The original site settings buffer</param>
    /// <param name = "_whsPhysDimUOMTempItem">The temp physical dimension buffer</param>
    private void createPhysicalDim(METInventItemOrderSetup  _metInventItemOrderSetupOrigItem,
                                    WHSPhysDimUOM _whsPhysDimUOMTempItem)
    {
        METWHSPhysDimUOMSite    metWHSPhysDimUOMSite, metWHSPhysDimUOMSiteTempPurch, metWHSPhysDimUOMSiteTempSales; 
        METPurchUnit            metPurchUnit    = inventItemPurchSetupTempItem.METPurchUnit;
        METSalesUnit            metSalesUnit    = inventItemSalesSetupTempItem.METSalesUnit;
       

        if (metPurchUnit != InventTable::find(_metInventItemOrderSetupOrigItem.ItemId).inventTableModuleInvent().UnitId)
        {
            select firstonly metWHSPhysDimUOMSiteTempPurch
                where metWHSPhysDimUOMSiteTempPurch.ItemId == metInventItemOrderSetupTempItem.ItemId
                && metWHSPhysDimUOMSiteTempPurch.UOM == metPurchUnit
                && metWHSPhysDimUOMSiteTempPurch.SiteId == metInventItemOrderSetupTempItem.SiteId;
            if (metWHSPhysDimUOMSiteTempPurch)
            {
                select firstonly forupdate metWHSPhysDimUOMSite
                where metWHSPhysDimUOMSite.ItemId == _metInventItemOrderSetupOrigItem.ItemId
                && metWHSPhysDimUOMSite.UOM == metWHSPhysDimUOMSiteTempPurch.UOM
                && metWHSPhysDimUOMSite.PhysDimId == metWHSPhysDimUOMSiteTempPurch.PhysDimId
                && metWHSPhysDimUOMSite.SiteId == metWHSPhysDimUOMSiteTempPurch.SiteId;

                if (metWHSPhysDimUOMSite.RecId)
                {
                    buf2Buf(metWHSPhysDimUOMSiteTempPurch, metWHSPhysDimUOMSite);
                    metWHSPhysDimUOMSite.ItemId = _metInventItemOrderSetupOrigItem.ItemId;
                    metWHSPhysDimUOMSite.update();
                }
                else
                {
                    buf2Buf(metWHSPhysDimUOMSiteTempPurch, metWHSPhysDimUOMSite);
                    metWHSPhysDimUOMSite.ItemId = _metInventItemOrderSetupOrigItem.ItemId;
                    metWHSPhysDimUOMSite.insert();
                }
            }

        }
        else if (metSalesUnit != InventTable::find(_metInventItemOrderSetupOrigItem.ItemId).inventTableModuleInvent().UnitId)
        {
            select firstonly metWHSPhysDimUOMSiteTempSales
                where metWHSPhysDimUOMSiteTempSales.ItemId == metInventItemOrderSetupTempItem.ItemId
                && metWHSPhysDimUOMSiteTempSales.UOM == metSalesUnit
                && metWHSPhysDimUOMSiteTempSales.SiteId == metWHSPhysDimUOMSiteTempPurch.SiteId;

            select firstonly forupdate metWHSPhysDimUOMSite
                where metWHSPhysDimUOMSite.ItemId == _metInventItemOrderSetupOrigItem.ItemId
                && metWHSPhysDimUOMSite.UOM == metWHSPhysDimUOMSiteTempSales.UOM
                && metWHSPhysDimUOMSite.PhysDimId == metWHSPhysDimUOMSiteTempSales.PhysDimId
                && metWHSPhysDimUOMSite.SiteId == metWHSPhysDimUOMSiteTempSales.SiteId;

            if (metWHSPhysDimUOMSite.RecId)
            {
                buf2Buf(metWHSPhysDimUOMSiteTempSales, metWHSPhysDimUOMSite);
                metWHSPhysDimUOMSite.ItemId = _metInventItemOrderSetupOrigItem.ItemId;
                metWHSPhysDimUOMSite.update();
            }
            else
            {
                buf2Buf(metWHSPhysDimUOMSiteTempSales, metWHSPhysDimUOMSite);
                metWHSPhysDimUOMSite.ItemId = _metInventItemOrderSetupOrigItem.ItemId;
                metWHSPhysDimUOMSite.insert();
            }
        }
        
    }

    /// <summary>
    /// Create the barcodes
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetupOriginal">The original item site settings buffer</param>
    /// <param name = "_metItemSiteSettingsSetupTemp">The item site settings buffer</param>
    private void createBarcode(METInventItemOrderSetup  _metItemSiteSettingsSetupOriginal, METInventItemOrderSetup  _metItemSiteSettingsSetupTemp)
    {
        InventItemBarcode inventItemBarcodeMainItem, inventItemBarcodeTempItem, inventItemBarcode;
        ReqItemTable reqItemTableBarcode;
        METReqItemTable metReqItemTableBarcode;
        InventDim inventDimBarcode;
        VendAccount vendAccount;

        select firstonly VendId, RecId from reqItemTableBarcode
            join metReqItemTableBarcode
            where reqItemTableBarcode.RecId == metReqItemTableBarcode.RefRecId
            exists join inventDimBarcode
            where inventDimBarcode.InventSiteId == _metItemSiteSettingsSetupOriginal.SiteId
            && inventDimBarcode.inventDimId == reqItemTableBarcode.CovInventDimId
            && reqItemTableBarcode.ItemId == _metItemSiteSettingsSetupTemp.ItemId;

        if(metReqItemTableBarcode.PendingVendAccountNumber)
        {
            vendAccount = metReqItemTableBarcode.PendingVendAccountNumber;
        }
        else
        {
            vendAccount = reqItemTableBarcode.VendId;
        }

        if (vendAccount)
        {
            METPurchUnit purchUnitTmpItem = inventItemPurchSetupTempItem.METPurchUnit;

            select firstonly inventItemBarcodeMainItem
            where inventItemBarcodeMainItem.itemId == _metItemSiteSettingsSetupOriginal.ItemId
            && inventItemBarcodeMainItem.UnitID == purchUnitTmpItem
            && InventTable::find(_metItemSiteSettingsSetupOriginal.ItemId).inventTableModuleInvent().UnitId != inventItemBarcodeMainItem.UnitID
            && inventItemBarcodeMainItem.METVendAccount == vendAccount;

            if (inventItemBarcodeMainItem && inventItemBarcodeMainItem.METDefault == NoYes::No)
            {
                inventItemBarcodeMainItem.selectForUpdate(true);
                inventItemBarcodeMainItem.METDefault = NoYes::Yes;
                inventItemBarcodeMainItem.update();
            }
        }

        // Create Sales unit barcode
        inventItemBarcodeMainItem.clear();
        inventItemBarcodeTempItem.clear();
        inventItemBarcode.clear();

        METSalesUnit metSalesUnitTmpItem = inventItemSalesSetupTempItem.METSalesUnit;

        select firstonly inventItemBarcodeMainItem where
            inventItemBarcodeMainItem.itemId == _metItemSiteSettingsSetupOriginal.ItemId
            && inventItemBarcodeMainItem.UnitID == metSalesUnitTmpItem
            && InventTable::find(_metItemSiteSettingsSetupOriginal.ItemId).inventTableModuleInvent().UnitId != inventItemBarcodeMainItem.UnitID
            && inventItemBarcodeMainItem.METVendAccount == vendAccount;

        if (inventItemBarcodeMainItem && inventItemBarcodeMainItem.METDefault == NoYes::No)
        {
            inventItemBarcodeMainItem.selectForUpdate(true);
            inventItemBarcodeMainItem.METDefault = NoYes::Yes;
            inventItemBarcodeMainItem.update();
        }
 
        while select inventItemBarcodeTempItem 
            where inventItemBarcodeTempItem.itemId == _metItemSiteSettingsSetupTemp.ItemId
                && inventItemBarcodeTempItem.METVendAccount == vendAccount
        {   
            select firstonly inventItemBarcodeMainItem
                where inventItemBarcodeMainItem.itemId == _metItemSiteSettingsSetupOriginal.ItemId
                    && inventItemBarcodeMainItem.UnitID == inventItemBarcodeTempItem.UnitID
                    && inventItemBarcodeMainItem.METVendAccount == vendAccount;

            if(!inventItemBarcodeMainItem.RecId)
            {                         
                inventItemBarcode.clear();
                buf2Buf(inventItemBarcodeTempItem, inventItemBarcode);
                inventItemBarcode.ItemId = _metItemSiteSettingsSetupOriginal.ItemId;

                if(inventItemPurchSetupTempItem.METPurchUnit == inventItemBarcodeTempItem.UnitID
                    || inventItemSalesSetupTempItem.METSalesUnit == inventItemBarcodeTempItem.UnitID)
                {
                    inventItemBarcode.METDefault = NoYes::Yes;
                }
                inventItemBarcode.insert();
            }

        }

    }

    /// <summary>
    /// Create vendor List price
    /// </summary>
    private void createVendorListPrice()
    {
        TransDate   currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        GUPVendPriceAdmTable    gupVendPriceAdmTable;
        GUPVendPriceAdmTrans    gupVendPriceAdmTransMainItem;
        METReqItemTable         metReqItemTable;
        METReqItemTableInventDimView metReqItemTableInventDimView;

        select firstonly RecId from metReqItemTableInventDimView
            exists join metReqItemTable
            where metReqItemTable.RefRecId == metReqItemTableInventDimView.ReqItemTableRecId
                && metReqItemTable.PendingVendChangeDate <= DateTimeUtil::getSystemDateTime()
                && metReqItemTable.PendingVendAccountNumber != ''
                && metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
                && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId;

        if(metReqItemTableInventDimView.RecId) //If there is pending vendor change, expire existing list prices and copy list prices from temp item to main item.
        {
            // Expire the existing supplier list prices for the main item.
            while select forupdate gupVendPriceAdmTable
            where gupVendPriceAdmTable.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            exists join gupVendPriceAdmTransMainItem
            where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
            && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupOrigItem.ItemId
            {
                gupVendPriceAdmTable.Status = GUPDisabledEnabled::Disabled;
                gupVendPriceAdmTable.update();

                METPurchUnit metpurchUnit       = inventItemPurchSetupOrigItem.METPurchUnit;

                while select forupdate gupVendPriceAdmTransMainItem
                order by gupVendPriceAdmTransMainItem.LineNum desc
                where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
                && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupOrigItem.ItemId
                && gupVendPriceAdmTransMainItem.UnitId == metpurchUnit
                && (!gupVendPriceAdmTransMainItem.ToDate
                || gupVendPriceAdmTransMainItem.ToDate > currentDate)
                {
                    if (gupVendPriceAdmTransMainItem)
                    {
                        if(gupVendPriceAdmTransMainItem.FromDate == currentDate)
                        {
                            gupVendPriceAdmTransMainItem.FromDate = currentDate-1;
                        }
                        gupVendPriceAdmTransMainItem.ToDate = currentDate-1; //Bug 341863: moving the date back by one day as requested.
                        gupVendPriceAdmTransMainItem.update();
                    }

                    if (gupVendPriceAdmTable && gupVendPriceAdmTable.Status == GUPDisabledEnabled::Disabled) // Enable journal if its disabled
                    {
                        gupVendPriceAdmTable.Status = GUPDisabledEnabled::Enabled;
                        gupVendPriceAdmTable.update();
                    }
                }
            }

            //Copy the supplier list price from temp item to main item.
            while select forupdate gupVendPriceAdmTable
            where gupVendPriceAdmTable.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            exists join gupVendPriceAdmTransMainItem
            where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
            && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupTempItem.ItemId
            {
                gupVendPriceAdmTable.Status = GUPDisabledEnabled::Disabled;
                gupVendPriceAdmTable.update();

                METPurchUnit metpurchUnit       = inventItemPurchSetupTempItem.METPurchUnit;

                while select forupdate gupVendPriceAdmTransMainItem
                order by gupVendPriceAdmTransMainItem.LineNum desc
                where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
                && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupTempItem.ItemId
                && gupVendPriceAdmTransMainItem.UnitId == metpurchUnit
                && (!gupVendPriceAdmTransMainItem.ToDate
                || gupVendPriceAdmTransMainItem.ToDate > currentDate)
                {                  
                    this.copyVendorListPriceFromTempToMainItem(gupVendPriceAdmTable.JournalNum);

                    if (gupVendPriceAdmTable && gupVendPriceAdmTable.Status == GUPDisabledEnabled::Disabled) // Enable journal if its disabled
                    {
                        gupVendPriceAdmTable.Status = GUPDisabledEnabled::Enabled;
                        gupVendPriceAdmTable.update();
                    }
                }
            }                   
        }
        else
        {
            while select forupdate gupVendPriceAdmTable
            where gupVendPriceAdmTable.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            exists join gupVendPriceAdmTransMainItem
            where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
            && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupTempItem.ItemId
            {
                gupVendPriceAdmTable.Status = GUPDisabledEnabled::Disabled;
                gupVendPriceAdmTable.update();

                METPurchUnit metpurchUnit       = inventItemPurchSetupOrigItem.METPurchUnit;

                while select forupdate gupVendPriceAdmTransMainItem
                order by gupVendPriceAdmTransMainItem.LineNum desc
                where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
                && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupOrigItem.ItemId
                && gupVendPriceAdmTransMainItem.UnitId == metpurchUnit
                && (!gupVendPriceAdmTransMainItem.ToDate
                || gupVendPriceAdmTransMainItem.ToDate > currentDate)
                {
                    if (gupVendPriceAdmTransMainItem)
                    {
                        if(gupVendPriceAdmTransMainItem.FromDate == currentDate)
                        {
                            gupVendPriceAdmTransMainItem.FromDate = currentDate-1;
                        }
                        gupVendPriceAdmTransMainItem.ToDate = currentDate-1; //Bug 341863: moving the date back by one day as requested.
                        gupVendPriceAdmTransMainItem.update();
                    }

                    this.copyVendorListPriceFromTempToMainItem(gupVendPriceAdmTable.JournalNum);

                    if (gupVendPriceAdmTable && gupVendPriceAdmTable.Status == GUPDisabledEnabled::Disabled) // Enable journal if its disabled
                    {
                        gupVendPriceAdmTable.Status = GUPDisabledEnabled::Enabled;
                        gupVendPriceAdmTable.update();
                    }
                }
            }
        }

        this.createVendorPriceTermAgreements();

    }

    /// <summary>
    /// Copy vendor list price from temp item to main item
    /// </summary>
    /// <param name = "_journalNum">Journal</param>
    private void copyVendorListPriceFromTempToMainItem(GUPVendPriceJournalNum _journalNum)
    {
        GUPVendPriceAdmTrans    gupVendPriceAdmTransTempItem, gupVendPriceAdmTrans;
        int                     countLoop = 0;
        TransDate   currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        METPurchUnit metpurchUnit = inventItemPurchSetupTempItem.METPurchUnit;

        RecordInsertList gupVendPriceAdmTransRecordInsertList = new RecordInsertList(tableNum(GUPVendPriceAdmTrans));

        while select gupVendPriceAdmTransTempItem
                where gupVendPriceAdmTransTempItem.JournalNum == _journalNum
                && gupVendPriceAdmTransTempItem.ItemNum == metInventItemOrderSetupTempItem.ItemId
                && gupVendPriceAdmTransTempItem.UnitId == metpurchUnit
                && (gupVendPriceAdmTransTempItem.FromDate >= currentDate
                || gupVendPriceAdmTransTempItem.ToDate >= currentDate
                || gupVendPriceAdmTransTempItem.ToDate == Global::dateNull())
        {
            countLoop++;
                
            gupVendPriceAdmTrans.initFromGUPVendPriceAdmTrans(gupVendPriceAdmTransTempItem);
                
            gupVendPriceAdmTrans.ItemNum        = metInventItemOrderSetupOrigItem.ItemId;            
            gupVendPriceAdmTrans.FromDate       = max(gupVendPriceAdmTransTempItem.FromDate, currentDate);
            gupVendPriceAdmTrans.JournalNum     = _journalNum;
            gupVendPriceAdmTrans.LineNum        = GUPVendPriceAdmTrans::lastLineNum(_journalNum) + countLoop;
                
            gupVendPriceAdmTransRecordInsertList.add(gupVendPriceAdmTrans);
        }
        gupVendPriceAdmTransRecordInsertList.insertDatabase();
    }

    /// <summary>
    /// Run Pricing routine
    /// </summary>
    private void runPricingRoutine()
    {        
        BatchHeader         header;
        SysRecurrenceData   sysRecurrenceData;
        Batch               batch;
        BatchJob            batchJob;
        BatchInfo           processBatchInfo;
        BatchRetries        noOfRetriesOnFailure = 4;
        //METGUPItemBasePriceCalcJob metGUPItemBasePriceCalcJob;
        GUPItemBasePriceCalcJob_All gupItemBasePriceCalcJob_All;
        GUPBasePriceVersion gupBasePriceVersion;
        #define.timeInSecondsDelay(10)
        
        

        //Created extension request to Microsoft 
            
        // Setup the RunBaseBatch Job

        select firstonly AllowPurch, AllowSales, AllowInventoryCost, BlockActivation, VersionId
            from gupBasePriceVersion                 
            where gupBasePriceVersion.InventSiteId == metInventItemOrderSetupOrigItem.SiteId;
        if(!gupBasePriceVersion)
        {
            return;
        }

        InventDim           inventdim;

        inventdim.InventSiteId = metInventItemOrderSetupOrigItem.SiteId;
        inventdim = InventDim::findOrCreate(inventdim);

        Query               query = new Query(queryStr(GUPItemBasePriceCalc));
        query.dataSourceTable(tableNum(InventTable)).findRange(fieldNum(InventTable, ItemId)).value(queryValue(metInventItemOrderSetupOrigItem.ItemId));

        header = BatchHeader::construct();
        gupItemBasePriceCalcJob_All = GUPItemBasePriceCalcJob_All::construct();
        gupItemBasePriceCalcJob_All.parmItemId(metInventItemOrderSetupOrigItem.ItemId);
        gupItemBasePriceCalcJob_All.parmSiteId(metInventItemOrderSetupOrigItem.SiteId);
        gupItemBasePriceCalcJob_All.parmCalcDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        gupItemBasePriceCalcJob_All.parmPurchPriceTransfer(gupBasePriceVersion.AllowPurch);
        gupItemBasePriceCalcJob_All.parmSalesPriceTransfer(gupBasePriceVersion.AllowSales);
        gupItemBasePriceCalcJob_All.parmCostPriceTransfer(gupBasePriceVersion.AllowInventoryCost);
        gupItemBasePriceCalcJob_All.parmBlockActivation(gupBasePriceVersion.BlockActivation);
        gupItemBasePriceCalcJob_All.parmBasePriceVersionId(gupBasePriceVersion.VersionId);
        gupItemBasePriceCalcJob_All.parmBasePriceActivatePrice(NoYes::Yes);
        gupItemBasePriceCalcJob_All.parmBasePriceDeltaCalculation(NoYes::Yes);
        gupItemBasePriceCalcJob_All.parmInventDimId(inventdim.inventDimId); 
        gupItemBasePriceCalcJob_All.parmMETIncludeClaimFromVendor(NoYes::Yes);
        gupItemBasePriceCalcJob_All.setMETQuery(query);

        processBatchInfo = gupItemBasePriceCalcJob_All.batchInfo();
        processBatchInfo.parmRetriesOnFailure(noOfRetriesOnFailure);
        processBatchInfo.parmCaption("@SYS24047" + strFmt(" - %1, %2", metInventItemOrderSetupOrigItem.SiteId, metInventItemOrderSetupOrigItem.ItemId));
        header.addTask(gupItemBasePriceCalcJob_All);

        // Set the recurrence data
        sysRecurrenceData = SysRecurrence::defaultRecurrence();
        sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, DateTimeUtil::addSeconds(DateTimeUtil::utcNow(), #timeInSecondsDelay));
        sysRecurrenceData = SysRecurrence::setRecurrenceEndAfter(sysRecurrenceData, 1);
        header.parmRecurrenceData(sysRecurrenceData);
        // Set the batch alert configurations
        header.parmAlerts(NoYes::No, NoYes::Yes, NoYes::No, NoYes::Yes, NoYes::No);
        header.save();     
    }

    /// <summary>
    /// Create vendor price term agreements
    /// </summary>
    private void createVendorPriceTermAgreements()
    {
        GUPPriceTermJournalTransEntity  gupPriceTermJournalTransEntityGroupBy, gupPriceTermJournalTransEntityMainItemFind;
        InventDim                       inventDim;
        GUPVendPriceAdmTable            gupVendPriceAdmTable;
        GUPVendPriceAdmTrans            gupVendPriceAdmTransMainItem;
        METReqItemTable                 metReqItemTable;
        METReqItemTableInventDimView    metReqItemTableInventDimView;

        select firstonly RecId from metReqItemTableInventDimView
            exists join metReqItemTable
            where metReqItemTable.RefRecId == metReqItemTableInventDimView.ReqItemTableRecId
                && metReqItemTable.PendingVendChangeDate <= DateTimeUtil::getSystemDateTime()
                && metReqItemTable.PendingVendAccountNumber != ''
                && metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
                && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId;

        if(metReqItemTableInventDimView.RecId) //If there is pending vendor change, expire existing price term agrements and copy price term agrements from temp item to main item.
        {
            select firstonly RecId from gupPriceTermJournalTransEntityMainItemFind
            exists join inventDim
            where (gupPriceTermJournalTransEntityMainItemFind.Line1 == metInventItemOrderSetupTempItem.ItemId
            || gupPriceTermJournalTransEntityMainItemFind.Line2 == metInventItemOrderSetupTempItem.ItemId)
            && inventDim.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            && gupPriceTermJournalTransEntityMainItemFind.METInventDimId == inventDim.inventDimId;

            if(gupPriceTermJournalTransEntityMainItemFind.RecId)
            {
                // Expire existing price term agrements for main item.
                while select gupPriceTermJournalTransEntityGroupBy
                group by gupPriceTermJournalTransEntityGroupBy.AgreementId, gupPriceTermJournalTransEntityGroupBy.METInventDimId
                exists join inventDim
                where (gupPriceTermJournalTransEntityGroupBy.Line1 == metInventItemOrderSetupOrigItem.ItemId
                || gupPriceTermJournalTransEntityGroupBy.Line2 == metInventItemOrderSetupOrigItem.ItemId)
                && inventDim.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
                && gupPriceTermJournalTransEntityGroupBy.METInventDimId == inventDim.inventDimId
                {
                    this.createVendorPriceTermAgreement(gupPriceTermJournalTransEntityGroupBy.AgreementId, inventItemPurchSetupOrigItem.METPurchUnit, metInventItemOrderSetupOrigItem.ItemId, true);
                }

                // Copy price term agrements from temp item to main item.
                while select gupPriceTermJournalTransEntityGroupBy
                group by gupPriceTermJournalTransEntityGroupBy.AgreementId, gupPriceTermJournalTransEntityGroupBy.METInventDimId
                exists join inventDim
                where (gupPriceTermJournalTransEntityGroupBy.Line1 == metInventItemOrderSetupTempItem.ItemId
                || gupPriceTermJournalTransEntityGroupBy.Line2 == metInventItemOrderSetupTempItem.ItemId)
                && inventDim.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
                && gupPriceTermJournalTransEntityGroupBy.METInventDimId == inventDim.inventDimId
                {
                    this.createVendorPriceTermAgreement(gupPriceTermJournalTransEntityGroupBy.AgreementId, inventItemPurchSetupTempItem.METPurchUnit, metInventItemOrderSetupTempItem.ItemId, false);
                }
            }
            else
            {
                // Expire existing price term agrements for main item.
                while select forupdate gupVendPriceAdmTable
                where gupVendPriceAdmTable.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
                exists join gupVendPriceAdmTransMainItem
                where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
                && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupOrigItem.ItemId
                {
                    this.createVendorPriceTermAgreement(gupVendPriceAdmTable.JournalNum, inventItemPurchSetupOrigItem.METPurchUnit, metInventItemOrderSetupOrigItem.ItemId, true);
                }

                // Copy price term agrements from temp item to main item.
                while select forupdate gupVendPriceAdmTable
                where gupVendPriceAdmTable.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
                exists join gupVendPriceAdmTransMainItem
                where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
                && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupTempItem.ItemId
                {
                    this.createVendorPriceTermAgreement(gupVendPriceAdmTable.JournalNum, inventItemPurchSetupTempItem.METPurchUnit, metInventItemOrderSetupTempItem.ItemId, false);
                }
            }
        }
        else
        {
            select firstonly RecId from gupPriceTermJournalTransEntityMainItemFind
            exists join inventDim
            where (gupPriceTermJournalTransEntityMainItemFind.Line1 == metInventItemOrderSetupTempItem.ItemId
            || gupPriceTermJournalTransEntityMainItemFind.Line2 == metInventItemOrderSetupTempItem.ItemId)
            && inventDim.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            && gupPriceTermJournalTransEntityMainItemFind.METInventDimId == inventDim.inventDimId;

            if(gupPriceTermJournalTransEntityMainItemFind.RecId)
            {
                while select gupPriceTermJournalTransEntityGroupBy
                group by gupPriceTermJournalTransEntityGroupBy.AgreementId, gupPriceTermJournalTransEntityGroupBy.METInventDimId
                exists join inventDim
                where (gupPriceTermJournalTransEntityGroupBy.Line1 == metInventItemOrderSetupTempItem.ItemId
                || gupPriceTermJournalTransEntityGroupBy.Line2 == metInventItemOrderSetupTempItem.ItemId)
                && inventDim.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
                && gupPriceTermJournalTransEntityGroupBy.METInventDimId == inventDim.inventDimId
                {
                    this.createVendorPriceTermAgreement(gupPriceTermJournalTransEntityGroupBy.AgreementId, inventItemPurchSetupOrigItem.METPurchUnit, metInventItemOrderSetupOrigItem.ItemId, true);
                }
            }
            else
            {
                while select forupdate gupVendPriceAdmTable
                where gupVendPriceAdmTable.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
                exists join gupVendPriceAdmTransMainItem
                where gupVendPriceAdmTransMainItem.JournalNum == gupVendPriceAdmTable.JournalNum
                && gupVendPriceAdmTransMainItem.ItemNum == metInventItemOrderSetupTempItem.ItemId
                {
                    this.createVendorPriceTermAgreement(gupVendPriceAdmTable.JournalNum, inventItemPurchSetupOrigItem.METPurchUnit, metInventItemOrderSetupOrigItem.ItemId, true);
                }
            }        
        }       
    }

    /// <summary>
    /// Create vendor price term agreement
    /// <summary>
    /// <param name = "_agreementId">AgreementId</param>
    /// <param name = "_metpurchUnit">PurchUnit</param>
    /// <param name = "_itemid">ItemId</param>
    /// <param name = "_isOriginalItem">Indicates whether the item is original item or temp item</param>
    private void createVendorPriceTermAgreement(GUPAgreementId _agreementId, METPurchUnit _metpurchUnit, ItemId _itemid, boolean _isOriginalItem)
    {
        TransDate                       currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        GUPPriceTermJournalTransEntity  gupPriceTermJournalTransEntityMainItem;
        GUPPriceTermJournalTable        gupPriceTermJournalTable = GUPPriceTermJournalTable::find(_agreementId, true);

        gupPriceTermJournalTable.Status = GUPDisabledEnabled::Disabled;
        gupPriceTermJournalTable.update();

        while select forupdate gupPriceTermJournalTransEntityMainItem
                    order by gupPriceTermJournalTransEntityMainItem.RecId desc
                    where gupPriceTermJournalTransEntityMainItem.AgreementId == gupPriceTermJournalTable.agreementId
                    && gupPriceTermJournalTransEntityMainItem.UnitId == _metpurchUnit
                    && (gupPriceTermJournalTransEntityMainItem.Line1 == _itemid
                    || gupPriceTermJournalTransEntityMainItem.Line2 == _itemid)
                    && (!gupPriceTermJournalTransEntityMainItem.ValidTo 
                    || gupPriceTermJournalTransEntityMainItem.ValidTo > currentDate)
        {
            if (_isOriginalItem)
            {
                if(gupPriceTermJournalTransEntityMainItem.ValidFrom > currentDate-1)
                {
                    gupPriceTermJournalTransEntityMainItem.ValidFrom = currentDate-1;
                }
                gupPriceTermJournalTransEntityMainItem.ValidTo = currentDate-1; //Bug 341863: moving the date back by one day as requested.           
                gupPriceTermJournalTransEntityMainItem.update();
            }

            this.copyVendorPriceTermFromTempToMainItem(gupPriceTermJournalTable.agreementId);

            if (gupPriceTermJournalTable.Status == GUPDisabledEnabled::Disabled)
            {
                gupPriceTermJournalTable.Status = GUPDisabledEnabled::Enabled;
                gupPriceTermJournalTable.update();
            }
        }
    
    }

    /// <summary>
    /// Copy vendor price term from temp item to main item
    /// </summary>
    /// <param name = "_agreementId">AgreementId</param>
    private void copyVendorPriceTermFromTempToMainItem(GUPAgreementId _agreementId)
    {
        TransDate                       currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        GUPPriceTermJournalTransEntity  gupPriceTermJournalTransEntityMainItem, gupPriceTermJournalTransEntityTempItem, gupPriceTermJournalTransEntity, gupPriceTermJournalTransEntityFind;
        int                             countLoop = 0;
        METPurchUnit metpurchUnit = inventItemPurchSetupTempItem.METPurchUnit;

        RecordInsertList gupPriceTermJournalTransEntityRecordInsertList = new RecordInsertList(tableNum(GUPPriceTermJournalTransEntity));

        while select gupPriceTermJournalTransEntityTempItem
                where gupPriceTermJournalTransEntityTempItem.AgreementId == _agreementId
                && gupPriceTermJournalTransEntityTempItem.UnitId == metpurchUnit
                && (gupPriceTermJournalTransEntityTempItem.Line1 == metInventItemOrderSetupTempItem.ItemId
                || gupPriceTermJournalTransEntityTempItem.Line2 == metInventItemOrderSetupTempItem.ItemId)
                && (gupPriceTermJournalTransEntityTempItem.ValidFrom >= currentDate
                || gupPriceTermJournalTransEntityTempItem.ValidTo >= currentDate
                || gupPriceTermJournalTransEntityTempItem.ValidTo == Global::dateNull())
        {
            countLoop++;

            select firstonly gupPriceTermJournalTransEntityFind
                where gupPriceTermJournalTransEntityFind.AgreementId == _agreementId
                && gupPriceTermJournalTransEntityFind.UnitId == metpurchUnit
                && (gupPriceTermJournalTransEntityFind.Line1 == metInventItemOrderSetupOrigItem.ItemId
                || gupPriceTermJournalTransEntityFind.Line2 == metInventItemOrderSetupOrigItem.ItemId)
                && gupPriceTermJournalTransEntityFind.METInventDimId == gupPriceTermJournalTransEntityTempItem.METInventDimId
                && gupPriceTermJournalTransEntityFind.Code == gupPriceTermJournalTransEntityTempItem.Code;

            if(!gupPriceTermJournalTransEntityFind.RecId)
            {
                buf2Buf(gupPriceTermJournalTransEntityTempItem, gupPriceTermJournalTransEntity);
                
                if (gupPriceTermJournalTransEntity.Line2 == inventItemPurchSetupTempItem.ItemId)
                {
                    gupPriceTermJournalTransEntity.Line2 = metInventItemOrderSetupOrigItem.ItemId;
                }
                else
                {
                    gupPriceTermJournalTransEntity.Line1 = metInventItemOrderSetupOrigItem.ItemId;
                }
                gupPriceTermJournalTransEntity.ValidFrom    = max(gupPriceTermJournalTransEntityTempItem.ValidFrom, currentDate);
                gupPriceTermJournalTransEntity.LineNum      = GUPPriceTermJournalTrans::lastLineNum(_agreementId) + countLoop;
                
                gupPriceTermJournalTransEntityRecordInsertList.add(gupPriceTermJournalTransEntity);
            }
        }
        gupPriceTermJournalTransEntityRecordInsertList.insertDatabase();
    }

