    }

    /// <summary>
    /// Reprice open sales orders
    /// </summary>
    private void rePriceOpenSalesOrders()
    {
        SalesTable                  salesTable;
        METSalesTable               metSalesTable, metSalesTableUpdate;
        SalesLine                   salesLine;
        METSalesLine                metSalesLine, metSalesLineUpdate;
        InventDim                   inventDim;
        EcoResProductUnitConverter  productUnitConverter;
        UnitOfMeasure               unitOfMeasureFrom;
        UnitOfMeasure               unitOfMeasureTo;
        UnitOfMeasureConversion     unitOfMeasureConversionDirect;   
        InventTable                 inventTable;
        EcoResProduct               ecoResProduct;
        InventTableModule           inventTableModuleOldPack;
        real                        factorA, factorB, convertedValue;
        int                         numberOfRecordsProcessed = 0;
        Set                         metSalesTableSet = new Set(Types::Int64);
        SetEnumerator               metSalesTableSetEnumerator;

        inventDim.clear();
        
        inventDim.InventSiteId  = metInventItemOrderSetupOrigItem.SiteId;
        inventDim               = InventDim::findDim(inventDim);
    
        try
        {
            while select RecId from salesTable
                where salesTable.SalesStatus == SalesStatus::Backorder
                join metSalesTable
                where metSalesTable.SalesTable == salesTable.RecId
                && metSalesTable.OrderProcessingStatus == METSalesOrderProcessingStatus::OptimisationCompleted
                    join salesLine
                    where salesLine.SalesId == salesTable.SalesId
                    && salesLine.ItemId == metInventItemOrderSetupOrigItem.ItemId
                    && salesLine.SalesStatus != SalesStatus::Canceled
                        join RecId, ItemId from inventTable 
                        where InventTable.ItemId == SalesLine.ItemId
                            join RecId from ecoResProduct
                            where ecoResProduct.RecId == inventTable.Product
                                join RecId from metSalesLine
                                where metSalesLine.SalesLine == salesLine.RecId
                                && metSalesLine.OrderExtractStatus == METOrderExtractStatus::Open
            {
                //Calculate Factor-A - Old unit to Sales Unit
                inventTableModuleOldPack    = InventTableModule::find(inventTable.ItemId, ModuleInventPurchSales::Invent);

                unitOfMeasureTo             = UnitOfMeasure::findBySymbol(inventTableModuleOldPack.UnitId);
                unitOfMeasureFrom           = UnitOfMeasure::findBySymbol(salesLine.SalesUnit);
                productUnitConverter        = EcoResProductUnitConverter::newForDistinctProduct(ecoResProduct.RecId, unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No);

                factorA = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                inventTable.ItemId,
                                salesLine.InventDimId,
                                salesLine.SalesQty,
                                salesLine.SalesUnit,
                                inventTableModuleOldPack.UnitId,
                                NoYes::Yes);

                //Calculate Factor-B 
                select firstonly Product
                    from inventTable
                    where inventTable.ItemId == metInventItemOrderSetupTempItem.ItemId;
                   
                unitOfMeasureFrom       = UnitOfMeasure::findBySymbol(inventTable.inventItemSalesSetup(inventDim.inventdimId).METSalesUnit);
                productUnitConverter    = EcoResProductUnitConverter::newForDistinctProduct(inventTable.Product, unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No);
                
                factorB = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                inventTable.ItemId,
                                salesLine.InventDimId,
                                1,
                                inventTable.inventItemSalesSetup(inventDim.inventdimId).METSalesUnit,
                                inventTableModuleOldPack.UnitId,
                                NoYes::Yes);             
                
                if (factorB != 0)
                {
                    unitOfMeasureConversionDirect   = UnitOfMeasureConversion::findByConversion(unitOfMeasureTo.RecId, unitOfMeasureFrom.RecId);
                    convertedValue                  = this.roundValue(factorA / factorB, unitOfMeasureTo, unitOfMeasureConversionDirect.Rounding);

                    salesline.metDeletePriceComponents();

                    ttsbegin;
                    salesLine.selectForUpdate(true);
                    salesLine.SalesUnit             = unitOfMeasureFrom.Symbol;
                    salesline.SalesQty              = convertedValue;

                    salesLine.update();

                    metSalesLineUpdate = METSalesLine::find(salesLine.RecId, true);
                    metSalesLineUpdate.addIndicator(METConstants::A);
                    metSalesLineUpdate.DelayPricing = METDelayPricing::PackChange;
                    metSalesLineUpdate.update();                                 
                    ttscommit;

                    if (!metSalesTableSet.in(metSalesTable.SalesTable))
                    {
                        metSalesTableSet.add(metSalesTable.SalesTable);
                    }
                    
                    ++numberOfRecordsProcessed;
                }  
             
                metSalesTableSetEnumerator = metSalesTableSet.getEnumerator();
                while (metSalesTableSetEnumerator.moveNext())
                {
                    metSalesTableUpdate = METSalesTable::findBySalesTable(metSalesTableSetEnumerator.current(), true);

                    if(metSalesTableUpdate.RecId)
                    {
                        ttsbegin;
                        metSalesTableUpdate.OrderProcessingStatus = METSalesOrderProcessingStatus::RepriceRequired;
                        metSalesTableUpdate.DelayPricing = METDelayPricing::PackChange;
                        metSalesTableUpdate.update();
                        ttscommit;
                    }
                }
            }

            if (mainSiteId == metInventItemOrderSetupOrigItem.SiteId)
            {
                info(strFmt("@MET:ItemPackChangeMessage", strFmt("@MET:PackChangeActionedForItemSite", metInventItemOrderSetupOrigItem.ItemId, mainSiteId), strFmt("@MET:RepricedSalesOrders", numberOfRecordsProcessed)));             
            }
            else         
            {
                info(strFmt("@MET:ItemPackChangeMessage", strFmt("@MET:ProcessingDependentSites", metInventItemOrderSetupOrigItem.ItemId, metInventItemOrderSetupOrigItem.SiteId), strFmt("@MET:RepricedSalesOrders", numberOfRecordsProcessed)));
            }                            
        }
        catch(Exception::Error)
        {
            throw Error("@SYS65081");
        }
    }

    /// <summary>
    /// Process NDC dependent sites
    /// </summary>
    private void processNDCDependentSites()
    {
        ReqItemTable reqItemTable;
        InventLocation inventLocation;
        InventSite inventSite;
        METReqItemTableInventDimView metReqItemTableInventDimView;

        while select metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
            exists join inventLocation
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationIdReqMain
            && inventLocation.METNDCWarehouse == NoYes::Yes
            && inventLocation.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
            exists join inventSite
            where inventSite.SiteId == metReqItemTableInventDimView.InventSiteId
            && inventSite.METNDCSite == NoYes::Yes
        {
            ItemId mainItem = metInventItemOrderSetupOrigItem.ItemId;
            ItemId tmpItem = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.InventSiteId).TempItemPackChg;

            if (tmpItem)
            {  

                METItemPackChangeHelper metItemPackChangeHelperDependentSites = new METItemPackChangeHelper();

                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetup(METInventItemOrderSetup::findByItemAndSite(mainItem, metReqItemTableInventDimView.InventSiteId));
                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetupTempItem(METInventItemOrderSetup::findByItemAndSite(tmpItem, metReqItemTableInventDimView.InventSiteId));

                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupOrigItem(InventItemPurchSetup::find(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupTempItem(InventItemPurchSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupOrigItem(InventItemSalesSetup::find(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupTempItem(InventItemSalesSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMOrigItem(METItemPackChangeHelper::getWhsPhysDimOUM(metInventItemOrderSetupOrigItem.ItemId));
                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMTempItem(METItemPackChangeHelper::getWhsPhysDimOUM(tmpItem));

                metItemPackChangeHelperDependentSites.startOperation_DependentSites();

                //Task110346_CB409-D365ToPIM-child site been added to list- start
                siteList.addEnd(metReqItemTableInventDimView.InventSiteId);
                warehouseList.addEnd(metReqItemTableInventDimView.InventLocationId);
                //Task110346_CB409-D365ToPIM-child site been added to list- end
                
            }
        }
    }

    /// <summary>
    /// Process CDS Dependent Sites
    /// </summary>
    private void processCDSDependentSites()
    {       
        InventLocation inventLocation;
        InventSiteId siteId = metInventItemOrderSetupOrigItem.SiteId;
        METReqItemTableInventDimView metReqItemTableInventDimView;
        
        while select metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
            exists join inventLocation
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
            && inventLocation.METCSDWarehouse == NoYes::Yes
            && metReqItemTableInventDimView.MainWarehouseInventSiteId == siteId
        {
            ItemId mainItem = metInventItemOrderSetupOrigItem.ItemId;
            ItemId tmpItem = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.InventSiteId).TempItemPackChg;

            if (tmpItem)
            {
                METItemPackChangeHelper metItemPackChangeHelperDependentSites = new METItemPackChangeHelper();

                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetup(METInventItemOrderSetup::findByItemAndSite(mainItem, metReqItemTableInventDimView.InventSiteId));
                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetupTempItem(METInventItemOrderSetup::findByItemAndSite(tmpItem, metReqItemTableInventDimView.InventSiteId));

                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupOrigItem(InventItemPurchSetup::find(mainItem, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupTempItem(InventItemPurchSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupOrigItem(InventItemSalesSetup::find(mainItem, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupTempItem(InventItemSalesSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMOrigItem(METItemPackChangeHelper::getWhsPhysDimOUM(mainItem));
                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMTempItem(METItemPackChangeHelper::getWhsPhysDimOUM(tmpItem));

                metItemPackChangeHelperDependentSites.startOperation_DependentSites();

                //Task110346_CB409-D365ToPIM-child site been added to list- start
                siteList.addEnd(metReqItemTableInventDimView.InventSiteId);
                warehouseList.addEnd(metReqItemTableInventDimView.InventLocationId);
                //Task110346_CB409-D365ToPIM-child site been added to list- end
            }
        }
    }

