    /// <summary>
    /// Gets the Item code table buffer
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <param name = "_inventUnit">InventUnitId</param>
    /// <returns>ItemBarCode</returns>
    public static ItemBarCode getInventItembarcode(ItemId _itemId, InventDim _inventDim, InventUnitId _inventUnit)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        InventItemBarcode inventItembarcode;

        select firstonly ReqItemTableRecId, VendId, RecId from metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == _itemId
            && metReqItemTableInventDimView.InventSiteId == _inventDim.InventSiteId
            && metReqItemTableInventDimView.VendId != '';

        if (!metReqItemTableInventDimView)
        {
            return '';
        }        
        else if (metReqItemTableInventDimView && metReqItemTableInventDimView.VendId)
        {
            select firstonly itemBarCode from inventItembarcode
                where inventItembarcode.itemId == _itemId
                && inventItembarcode.METDefault == NoYes::Yes
                && inventItembarcode.METVendAccount == metReqItemTableInventDimView.VendId
                && inventItembarcode.UnitID == _inventUnit;
        }

        return inventItembarcode.itemBarCode;
    }

    /// <summary>
    /// Get vendor List price
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <returns>GUPVendPriceAmount</returns>
    public static GUPVendPriceAmount getVendorListPrice(ItemId _itemId, InventDim _inventDim)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        InventDim       inventDimPrice;
        InventLocation  inventLocation;
        GUPVendPriceAdmTrans gupVendPriceAdmTrans;
        GUPVendPriceAmount amount;
        GUPVendPriceJournalNum journalNum;
        date curDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        select firstonly RecId, VendId, InventLocationId from metReqItemTableInventDimView
            join InventLocationId,METNDCWarehouse from inventLocation
            where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
            && metReqItemTableInventDimView.InventSiteId == _inventDim.InventSiteId
            && metReqItemTableInventDimView.ItemId == _itemId;

        if (metReqItemTableInventDimView && !inventLocation.METNDCWarehouse)
        {
            journalNum = metReqItemTableInventDimView.VendId + METConstants::hyphen + metReqItemTableInventDimView.InventLocationId;

            select firstonly Amount from gupVendPriceAdmTrans
                order by gupVendPriceAdmTrans.LineNum
                where gupVendPriceAdmTrans.JournalNum == journalNum
                && gupVendPriceAdmTrans.ItemNum == _itemId
                && gupVendPriceAdmTrans.FromDate <= curDate
                && (gupVendPriceAdmTrans.ToDate  >= curDate || gupVendPriceAdmTrans.ToDate == dateNull())
                exists join inventDimPrice
                where inventDimPrice.inventDimId == gupVendPriceAdmTrans.InventDimId
                && inventDimPrice.InventSiteId == _inventDim.InventSiteId;

            amount = gupVendPriceAdmTrans.Amount;
            
        } 
        else if(metReqItemTableInventDimView && inventLocation.METNDCWarehouse)
        {
            inventLocation.clear();

            select firstonly RecId, VendId from metReqItemTableInventDimView
                where metReqItemTableInventDimView.InventSiteId == _inventDim.InventSiteId
                && metReqItemTableInventDimView.ItemId == _itemId
                join RecId, InventLocationId from inventLocation
                where inventLocation.InventLocationId == metReqItemTableInventDimView.InventLocationId
                && inventLocation.METNDCWarehouse == NoYes::Yes
                && metReqItemTableInventDimView.ReqPOType == ReqPOType::Purch;

            journalNum = metReqItemTableInventDimView.VendId +  METConstants::hyphen + inventLocation.InventLocationId;
        
            select firstonly Amount from gupVendPriceAdmTrans
                order by gupVendPriceAdmTrans.LineNum
                where gupVendPriceAdmTrans.JournalNum == journalNum
                && gupVendPriceAdmTrans.ItemNum == _itemId
                && gupVendPriceAdmTrans.FromDate <= curDate
                && (gupVendPriceAdmTrans.ToDate >= curDate || gupVendPriceAdmTrans.ToDate == dateNull())
                exists join inventDimPrice
                    where inventDimPrice.InventLocationId == inventLocation.InventLocationId
                    && inventDimPrice.InventSiteId == _inventDim.InventSiteId;

            amount = gupVendPriceAdmTrans.Amount;
        }        
        
        return amount;
        
    }

