    /// <summary>
    /// Round the value using unit conversion rounding rules
    /// </summary>
    /// <param name = "_value">Value to round</param>
    /// <param name = "_toUnit">To unit</param>
    /// <param name = "_rounding">Round method</param>
    /// <returns>round value</returns>
    private real roundValue(real _value, UnitOfMeasure _toUnit, UnitOfMeasureConversionRounding _rounding)
    {
        real    ret;
        int     sign    = 1;
        
        switch (_rounding)
        {
            case UnitOfMeasureConversionRounding::Nearest   :
                ret = decRound(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;

            case UnitOfMeasureConversionRounding::Up        :
                ret = roundUpDec(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;

            case UnitOfMeasureConversionRounding::Down      :
                ret = roundDownDec(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;
        }

        return sign * ret;
    }

    /// <summary>
    /// Rounds the value down
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "numDec">Number of decimals</param>
    /// <returns>real</returns>
    static real roundDownDec(real value, int numDec)
    {
        real unit   = 1;
        int num     = numDec;
        while (num > 0)
        {
            unit        = unit/10;
            num         = num-1;
        }

        return roundDown(value, unit);
    }

    /// <summary>
    /// Rounds the value up
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "unit">Rounding unit</param>
    /// <returns>real</returns>
    static real roundUp(real value, real unit)
    {
        real    roundedValue;

        roundedValue = round(value,unit);
        // Check for special case
        if (value== roundedValue)
        {
            return value;
        }
        // for numerical reasons we subtract the major part of the number before rounding
        return round(value - roundedValue + unit/2, unit) + roundedValue;
        
    }

    /// <summary>
    /// Round up to decimal
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "numDec">Number of decimals</param>
    /// <returns>real</returns>
    static real roundUpDec(real value, int numDec)
    {
        real unit = 1;
        int num     = numDec;
        while (num > 0)
        {
            unit        = unit/10;
            num         = num-1;
        }

        return roundUp(value,unit);
    }

/// <summary>
/// The rounding decimal precision
/// </summary>
/// <param name = "_toUnit">To unit</param>
/// <returns>Precision value</returns>
private UnitOfMeasureDecimalPrecision roundingDecimalPrecision(RecId _toUnit)
{
    return  UnitOfMeasure::find(_toUnit).DecimalPrecision;
}

    /// <summary>
    /// Run vendor change request
    /// </summary>
    private void runVendorChangeRequest()
    {
        METReqItemTable metReqItemTable;
        METReqItemTableInventDimView metReqItemTableInventDimView;

        while select ItemId, CovInventDimId, ReqPOType, InventLocationIdReqMain, VendId, InventSiteId
            from metReqItemTableInventDimView
            exists join metReqItemTable
            where metReqItemTable.RefRecId == metReqItemTableInventDimView.ReqItemTableRecId
            && metReqItemTable.PendingVendChangeDate <= DateTimeUtil::getSystemDateTime()
            && metReqItemTable.PendingVendAccountNumber != ''
            && metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId
        {
            METVendorChangeRequestController    controller  = METVendorChangeRequestController::construct();
            METVendorChangeRequestContract      contract    = controller ? controller.getDataContractObject() : null;

            if (!contract)
            {
                throw error(Error::wrongUseOfFunction(funcName()));
            }

            // Set contract fields
            contract.parmItemId(metReqItemTableInventDimView.ItemId);
            contract.parmInventSiteId(metReqItemTableInventDimView.InventSiteId);
            contract.parmCalledFromDefaultForm(true);

            controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch); // Set execution mode
            controller.parmShowDialog(false); // Prevent dialog
            controller.parmLoadFromSysLastValue(false); // Prevent loading from last value
            controller.parmInBatch(true);
            controller.parmDialogCaption(strFmt("@MET:VendChangeReqBatch @DOMLabels:DOMItemId - %1 @SYS177684 - %2",metInventItemOrderSetupOrigItem.ItemId, metInventItemOrderSetupOrigItem.SiteId));
            // Start operation
            controller.startOperation();
        }
    }

///Task110346_CB409-D365ToPIM
/// <summary>
/// trigger the item pack change business event on completion
/// </summary>
/// <param name = "_itemId">Itemid</param>
/// <param name = "_tempItemPackChg">Temp item</param>
/// <param name = "_inventSiteId">InventSite list</param>
private void triggerItemPackchangeCompleteBusinessEvent(ItemId _itemId, METTempItemPackChg _tempItemPackChg, list _inventSiteId, List _inventLocationIdList)
{
    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METItemPackChangeCompletedBusinessEvent)))
    {
        METItemPackChangeCompletedBusinessEvent::newFromItemPackChangeCompleted(_itemId, _tempItemPackChg, _inventSiteId, _inventLocationIdList).send();
    }
}

    /// <summary>
    /// Process Campbells subordinate Sites
    /// </summary>
    private void processCampbellsSubOrdinateSites()
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;
        METSiteControllingAndSubOrdinateSetup metSiteControllingAndSubOrdinateSetup;

        while select metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
            exists join metSiteControllingAndSubOrdinateSetup
            where metSiteControllingAndSubOrdinateSetup.SiteId == metReqItemTableInventDimView.InventSiteId
            && metSiteControllingAndSubOrdinateSetup.ControllingSiteId == metInventItemOrderSetupOrigItem.SiteId
            && metSiteControllingAndSubOrdinateSetup.IsControllingSite ==  NoYes::No
        {
            ItemId mainItem = metInventItemOrderSetupOrigItem.ItemId;
            ItemId tmpItem = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.InventSiteId).TempItemPackChg;

            if (tmpItem)
            {

                METItemPackChangeHelper metItemPackChangeHelperDependentSites = new METItemPackChangeHelper();

                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetup(METInventItemOrderSetup::findByItemAndSite(mainItem, metReqItemTableInventDimView.InventSiteId));
                metItemPackChangeHelperDependentSites.parmMETInventItemOrderSetupTempItem(METInventItemOrderSetup::findByItemAndSite(tmpItem, metReqItemTableInventDimView.InventSiteId));

                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupOrigItem(InventItemPurchSetup::find(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemPurchSetupTempItem(InventItemPurchSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupOrigItem(InventItemSalesSetup::find(metInventItemOrderSetupOrigItem.ItemId, metReqItemTableInventDimView.CovInventDimId));
                metItemPackChangeHelperDependentSites.parmInventItemSalesSetupTempItem(InventItemSalesSetup::find(tmpItem, metReqItemTableInventDimView.CovInventDimId));

                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMOrigItem(METItemPackChangeHelper::getWhsPhysDimOUM(metInventItemOrderSetupOrigItem.ItemId));
                metItemPackChangeHelperDependentSites.parmWHSPhysDimUOMTempItem(METItemPackChangeHelper::getWhsPhysDimOUM(tmpItem));

                metItemPackChangeHelperDependentSites.startOperation_DependentSites();

                siteList.addEnd(metReqItemTableInventDimView.InventSiteId);
                warehouseList.addEnd(metReqItemTableInventDimView.InventLocationId);
            }
        }
    }

/// <summary>
/// Check CDS site
/// </summary>
/// <returns>METSiteControllingAndSubOrdinateSetup buffer</returns>
private METSiteControllingAndSubOrdinateSetup getCampbellsControllingSite()
{
    METSiteControllingAndSubOrdinateSetup metSiteControllingAndSubOrdinateSetup = METSiteControllingAndSubOrdinateSetup::findBySite(metInventItemOrderSetupOrigItem.SiteId);        
    
    return metSiteControllingAndSubOrdinateSetup;
}

    /// <summary>
    /// Populate warehouse list to business event
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    /// <param name = "_itemId">ItemId</param>
    public void populateWarehouseToBE(InventSiteId _siteId, ItemId _itemId)
    {
        METReqItemTableInventDimView metReqItemTableInventDimView;

        while select InventLocationId from metReqItemTableInventDimView
            where metReqItemTableInventDimView.ItemId == _itemId
            && metReqItemTableInventDimView.InventSiteId == _siteId
        {
            warehouseList.addEnd(metReqItemTableInventDimView.InventLocationId);
        }
    }

    /// <summary>
    /// Check pending vendor change request with future date for the item and site combination, if exist then throw error to user.
    /// </summary>
    /// <returns>True or false</returns>
    private boolean checkVendorChangeRequest()
    {
        METReqItemTable metReqItemTable;
        METReqItemTableInventDimView metReqItemTableInventDimView;

        boolean ret = true;

        select firstonly RecId from metReqItemTableInventDimView
            exists join metReqItemTable
            where metReqItemTable.RefRecId == metReqItemTableInventDimView.ReqItemTableRecId
                && metReqItemTable.PendingVendChangeDate > DateTimeUtil::getSystemDateTime()
                && metReqItemTable.PendingVendAccountNumber != ''
                && metReqItemTableInventDimView.ItemId == metInventItemOrderSetupOrigItem.ItemId
                && metReqItemTableInventDimView.InventSiteId == metInventItemOrderSetupOrigItem.SiteId;
        
        if (metReqItemTableInventDimView.RecId)
        {
            ret = checkFailed("@MET:ValidationPackChangeVendorChangeRequest");
        }

        return ret;
    }
